import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    nums = list(map(int, data))
    idx = 0
    t = 1
    # Heuristic to detect if first number is test count
    if len(nums) >= 3 and (len(nums) - 1) % 2 == 0:
        possible_t = nums[0]
        if possible_t == (len(nums) - 1) // 2:
            t = possible_t
            idx = 1
        else:
            t = len(nums) // 2
            idx = 0
    else:
        t = len(nums) // 2
        idx = 0

    out_lines = []
    for _ in range(t):
        if idx + 1 >= len(nums):
            break
        n = nums[idx]
        k = nums[idx + 1]
        idx += 2

        l = -1
        r = n + 1
        while r - l > 1:
            m = (l + r) // 2
            val = (n - m) * (n - m + 1) // 2 - m
            if val > k:
                l = m
            else:
                r = m
        out_lines.append(str(r))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

